package com.ncpl.sales.cashflow.service;
import com.ncpl.sales.cashflow.entity.*;import com.ncpl.sales.cashflow.repository.*;
import java.time.*;import java.math.BigDecimal;import java.util.*;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
class MonthlyRetentionStatementTest {
 final InvoiceRepository invoices=mock(InvoiceRepository.class);final FinanceCashPlanEntryRepository entries=mock(FinanceCashPlanEntryRepository.class);
 final FinanceCashPlanService service=new FinanceCashPlanService(invoices,entries,mock(FinanceCashPlanSettingsRepository.class),mock(RecurringTransactionRepository.class));
 InvoiceEntity bill(String amount,boolean retained,boolean incoming,LocalDate expected){InvoiceEntity b=new InvoiceEntity();b.setCustomerName(retained?"Against handing over":"Retention named ordinary ledger");b.setRetention(retained);b.setInvoiceType(incoming?InvoiceEntity.InvoiceType.INFLOW:InvoiceEntity.InvoiceType.OUTFLOW);b.setInvoiceValue(new BigDecimal(amount));b.setDueDate(LocalDate.now());b.setExpectedCashDate(expected);return b;}
 FinanceCashPlanEntryEntity manual(String type,String amount){FinanceCashPlanEntryEntity e=new FinanceCashPlanEntryEntity();e.setEntryType(type);e.setAmount(new BigDecimal(amount));e.setPlannedDate(LocalDate.now());return e;}
 void seed(){InvoiceEntity remainder=bill("200",true,true,null);remainder.setRetentionBalanceOnly(true);remainder.setDueDate(null);InvoiceEntity credit=bill("-20",true,true,null);credit.setRetentionBalanceOnly(true);credit.setDueDate(null);when(invoices.findBySource("TALLY")).thenReturn(Arrays.asList(bill("1000",false,true,null),bill("600",false,false,null),bill("250",true,true,LocalDate.now()),bill("40",true,false,LocalDate.now()),remainder,credit));when(entries.findByActiveTrueAndPlannedDateBetweenOrderByPlannedDateAsc(any(),any())).thenReturn(Arrays.asList(manual(FinanceCashPlanService.MANUAL_CASH_IN,"50"),manual(FinanceCashPlanService.MANUAL_CASH_OUT,"25")));}
 Map period(Map plan){return (Map)((List)plan.get("periods")).get(0);}
 @Test void normalStatementExcludesRetentionAndKeepsManualAmounts(){seed();Map result=service.buildPlan(YearMonth.now(),3);Map p=period(result);assertEquals(new BigDecimal("1000"),p.get("tallyCashIn"));assertEquals(new BigDecimal("1050"),p.get("totalCashIn"));assertEquals(new BigDecimal("625"),p.get("totalCashOut"));assertEquals(new BigDecimal("430"),result.get("retentionReceivablesBalance"));assertEquals(new BigDecimal("180"),result.get("retentionAwaitingDateReceivables"));assertEquals(2,result.get("retentionAwaitingDateCount"));}
 @Test void retentionViewUsesExpectedDatesAndDoesNotAddNormalManualAdjustments(){seed();Map result=service.buildPlan(YearMonth.now(),3,true);Map p=period(result);assertEquals(new BigDecimal("250"),p.get("totalCashIn"));assertEquals(new BigDecimal("40"),p.get("totalCashOut"));assertEquals(BigDecimal.ZERO,p.get("manualCashIn"));assertEquals(0,result.get("manualEntryCount"));assertEquals(0,result.get("overdueMovedToFirstMonthCount"));}
 @Test void aDueDateAloneNeverSchedulesRetention(){InvoiceEntity b=bill("300",true,true,null);when(invoices.findBySource("TALLY")).thenReturn(Collections.singletonList(b));Map result=service.buildPlan(YearMonth.now(),3,true);assertEquals(BigDecimal.ZERO,period(result).get("tallyCashIn"));assertEquals(new BigDecimal("300"),result.get("retentionAwaitingDateReceivables"));}
 @Test void expiredReleaseDateNeedsReschedulingRatherThanBeingRolledIntoFirstMonth(){when(invoices.findBySource("TALLY")).thenReturn(Collections.singletonList(bill("80",true,true,LocalDate.now().minusDays(2))));Map result=service.buildPlan(YearMonth.now(),3,true);assertEquals(BigDecimal.ZERO,period(result).get("tallyCashIn"));assertEquals(1,result.get("retentionAwaitingDateCount"));assertEquals(0,result.get("overdueMovedToFirstMonthCount"));}
 @Test void scheduledRetentionOutsideSelectedMonthsDoesNotBecomeUnscheduled(){when(invoices.findBySource("TALLY")).thenReturn(Collections.singletonList(bill("80",true,true,YearMonth.now().plusMonths(5).atDay(1))));Map result=service.buildPlan(YearMonth.now(),3,true);assertEquals(BigDecimal.ZERO,period(result).get("tallyCashIn"));assertEquals(0,result.get("retentionAwaitingDateCount"));assertEquals(new BigDecimal("80"),result.get("retentionReceivablesBalance"));}
}
